using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests;

public static class TestHelpers
{
    public static SchoolContext CreateInMemoryContext(string? dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName)
            .Options;
        var context = new SchoolContext(options);
        return context;
    }

    public static SchoolContext CreateSeededContext(string? dbName = null)
    {
        var context = CreateInMemoryContext(dbName);
        SeedData(context);
        return context;
    }

    public static void SeedData(SchoolContext context)
    {
        var instructor1 = new Instructor
        {
            ID = 1,
            FirstMidName = "Kim",
            LastName = "Abercrombie",
            HireDate = DateTime.Parse("1995-03-11")
        };
        var instructor2 = new Instructor
        {
            ID = 2,
            FirstMidName = "Fadi",
            LastName = "Fakhouri",
            HireDate = DateTime.Parse("2002-07-06")
        };

        context.Instructors.AddRange(instructor1, instructor2);

        var dept1 = new Department
        {
            DepartmentID = 1,
            Name = "English",
            Budget = 350000,
            StartDate = DateTime.Parse("2007-09-01"),
            InstructorID = 1
        };
        var dept2 = new Department
        {
            DepartmentID = 2,
            Name = "Mathematics",
            Budget = 100000,
            StartDate = DateTime.Parse("2007-09-01"),
            InstructorID = 2
        };

        context.Departments.AddRange(dept1, dept2);

        var course1 = new Course
        {
            CourseID = 1050,
            Title = "Chemistry",
            Credits = 3,
            DepartmentID = 1,
            Department = dept1
        };
        var course2 = new Course
        {
            CourseID = 4022,
            Title = "Microeconomics",
            Credits = 3,
            DepartmentID = 2,
            Department = dept2
        };

        context.Courses.AddRange(course1, course2);

        var student1 = new Student
        {
            ID = 1,
            FirstMidName = "Carson",
            LastName = "Alexander",
            EnrollmentDate = DateTime.Parse("2010-09-01")
        };
        var student2 = new Student
        {
            ID = 2,
            FirstMidName = "Meredith",
            LastName = "Alonso",
            EnrollmentDate = DateTime.Parse("2012-09-01")
        };
        var student3 = new Student
        {
            ID = 3,
            FirstMidName = "Arturo",
            LastName = "Anand",
            EnrollmentDate = DateTime.Parse("2013-09-01")
        };

        context.Students.AddRange(student1, student2, student3);

        var enrollment1 = new Enrollment
        {
            EnrollmentID = 1,
            CourseID = 1050,
            StudentID = 1,
            Grade = Grade.A
        };
        var enrollment2 = new Enrollment
        {
            EnrollmentID = 2,
            CourseID = 4022,
            StudentID = 2,
            Grade = Grade.B
        };

        context.Enrollments.AddRange(enrollment1, enrollment2);

        var courseAssignment = new CourseAssignment
        {
            CourseID = 1050,
            InstructorID = 1
        };

        context.CourseAssignments.Add(courseAssignment);

        context.SaveChanges();
    }
}

using Xunit;
using ContosoUniversity;
using System.Collections.Generic;
using System.Linq;

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Constructor_SetsPageIndex()
    {
        // Arrange & Act
        var list = new PaginatedList<int>(new List<int> { 1, 2, 3 }, 10, 2, 3);

        // Assert
        Assert.Equal(2, list.PageIndex);
    }

    [Fact]
    public void Constructor_CalculatesTotalPages_RoundsUp()
    {
        // 10 items, page size 3 => ceil(10/3) = 4
        var list = new PaginatedList<int>(new List<int> { 1, 2, 3 }, 10, 1, 3);

        Assert.Equal(4, list.TotalPages);
    }

    [Fact]
    public void Constructor_CalculatesTotalPages_ExactDivision()
    {
        // 9 items, page size 3 => 3 pages
        var list = new PaginatedList<int>(new List<int> { 1, 2, 3 }, 9, 1, 3);

        Assert.Equal(3, list.TotalPages);
    }

    [Fact]
    public void Constructor_AddsItemsToList()
    {
        var items = new List<string> { "a", "b", "c" };
        var list = new PaginatedList<string>(items, 20, 1, 5);

        Assert.Equal(3, list.Count);
        Assert.Equal("a", list[0]);
        Assert.Equal("b", list[1]);
        Assert.Equal("c", list[2]);
    }

    [Fact]
    public void HasPreviousPage_FirstPage_ReturnsFalse()
    {
        var list = new PaginatedList<int>(new List<int> { 1 }, 10, 1, 5);

        Assert.False(list.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_SecondPage_ReturnsTrue()
    {
        var list = new PaginatedList<int>(new List<int> { 1 }, 10, 2, 5);

        Assert.True(list.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_LastPage_ReturnsFalse()
    {
        // 10 items, page size 5 => 2 pages; on page 2
        var list = new PaginatedList<int>(new List<int> { 1 }, 10, 2, 5);

        Assert.False(list.HasNextPage);
    }

    [Fact]
    public void HasNextPage_FirstPage_ReturnsTrue()
    {
        var list = new PaginatedList<int>(new List<int> { 1 }, 10, 1, 5);

        Assert.True(list.HasNextPage);
    }

    [Fact]
    public void HasNextPage_OnlyOnePage_ReturnsFalse()
    {
        var list = new PaginatedList<int>(new List<int> { 1, 2 }, 2, 1, 5);

        Assert.False(list.HasNextPage);
    }

    [Theory]
    [InlineData(1, 10, 3, false, true)]   // page 1 of 4
    [InlineData(2, 10, 3, true, true)]    // page 2 of 4
    [InlineData(4, 10, 3, true, false)]   // page 4 of 4 (last page)
    [InlineData(1, 3, 3, false, false)]   // only 1 page
    public void Navigation_Properties_VariousPages(int pageIndex, int totalCount, int pageSize, bool expectedHasPrev, bool expectedHasNext)
    {
        var list = new PaginatedList<int>(new List<int> { 1 }, totalCount, pageIndex, pageSize);

        Assert.Equal(expectedHasPrev, list.HasPreviousPage);
        Assert.Equal(expectedHasNext, list.HasNextPage);
    }

    [Fact]
    public void Create_ReturnsCorrectPageOfItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 2, 10);

        // Assert
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(3, result.TotalPages);  // ceil(25/10) = 3
        Assert.Equal(10, result.Count);      // 10 items on page 2
        Assert.Equal(11, result[0]);         // first item on page 2
        Assert.Equal(20, result[9]);         // last item on page 2
    }

    [Fact]
    public void Create_LastPage_ReturnsRemainingItems()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(source, 3, 10);

        Assert.Equal(3, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(5, result.Count);     // only 5 items on last page
        Assert.Equal(21, result[0]);
        Assert.Equal(25, result[4]);
    }

    [Fact]
    public void Create_FirstPage_SkipsNothing()
    {
        var source = Enumerable.Range(1, 5).AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 3);

        Assert.Equal(1, result.PageIndex);
        Assert.Equal(2, result.TotalPages);
        Assert.Equal(3, result.Count);
        Assert.Equal(1, result[0]);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        var source = Enumerable.Empty<int>().AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
        Assert.Equal(1, result.PageIndex);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Constructor_SingleItemCount_SinglePage()
    {
        var list = new PaginatedList<string>(new List<string> { "only" }, 1, 1, 10);

        Assert.Equal(1, list.TotalPages);
        Assert.False(list.HasPreviousPage);
        Assert.False(list.HasNextPage);
    }
}

using Xunit;
using ContosoUniversity.Services;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests;

public class NotificationServiceTests
{
    [Fact]
    public void SendNotification_Create_EnqueuesNotificationWithCorrectMessage()
    {
        // Arrange
        var service = new NotificationService();

        // Act
        service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");

        // Assert
        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("Student 'John Doe'", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_Update_GeneratesUpdateMessage()
    {
        var service = new NotificationService();

        service.SendNotification("Course", "42", "Calculus", EntityOperation.UPDATE, "teacher");

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("UPDATE", notification.Operation);
        Assert.Contains("updated", notification.Message);
        Assert.Contains("Course 'Calculus'", notification.Message);
    }

    [Fact]
    public void SendNotification_Delete_GeneratesDeleteMessage()
    {
        var service = new NotificationService();

        service.SendNotification("Department", "5", "Math", EntityOperation.DELETE, "admin");

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("DELETE", notification.Operation);
        Assert.Contains("deleted", notification.Message);
        Assert.Contains("Department 'Math'", notification.Message);
    }

    [Fact]
    public void SendNotification_NullDisplayName_UsesIdInMessage()
    {
        var service = new NotificationService();

        service.SendNotification("Student", "99", null, EntityOperation.CREATE, "admin");

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("Student (ID: 99)", notification.Message);
    }

    [Fact]
    public void SendNotification_EmptyDisplayName_UsesIdInMessage()
    {
        var service = new NotificationService();

        service.SendNotification("Student", "99", "  ", EntityOperation.UPDATE, "admin");

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("Student (ID: 99)", notification.Message);
    }

    [Fact]
    public void SendNotification_NullUserName_DefaultsToSystem()
    {
        var service = new NotificationService();

        service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_OverloadWithoutDisplayName_Works()
    {
        var service = new NotificationService();

        service.SendNotification("Instructor", "5", EntityOperation.DELETE, "admin");

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Instructor", notification.EntityType);
        Assert.Equal("5", notification.EntityId);
        Assert.Equal("DELETE", notification.Operation);
        Assert.Contains("Instructor (ID: 5)", notification.Message);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var service = new NotificationService();

        // Drain any existing notifications from the static queue
        while (service.ReceiveNotification() != null) { }

        var result = service.ReceiveNotification();

        Assert.Null(result);
    }

    [Fact]
    public void SendAndReceive_FIFO_Order()
    {
        var service = new NotificationService();

        // Drain queue first
        while (service.ReceiveNotification() != null) { }

        service.SendNotification("A", "1", "First", EntityOperation.CREATE, "user");
        service.SendNotification("B", "2", "Second", EntityOperation.UPDATE, "user");
        service.SendNotification("C", "3", "Third", EntityOperation.DELETE, "user");

        var first = service.ReceiveNotification();
        var second = service.ReceiveNotification();
        var third = service.ReceiveNotification();

        Assert.Equal("A", first!.EntityType);
        Assert.Equal("B", second!.EntityType);
        Assert.Equal("C", third!.EntityType);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToNonDefault()
    {
        var service = new NotificationService();

        service.SendNotification("Test", "1", "Item", EntityOperation.CREATE, "user");

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.NotEqual(default, notification.CreatedAt);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        var service = new NotificationService();

        // MarkAsRead is a no-op for in-memory implementation, just ensure no exceptions
        var exception = Record.Exception(() => service.MarkAsRead(42));
        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();
        var exception = Record.Exception(() => service.Dispose());
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_SetsIsReadToFalse()
    {
        var service = new NotificationService();

        service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, "user");

        var notification = service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.False(notification.IsRead);
    }
}

