    [Theory]
    [InlineData(".jpg")]
    [InlineData(".jpeg")]
    [InlineData(".png")]
    [InlineData(".gif")]
    [InlineData(".bmp")]
    public void Create_POST_ValidImageExtension_DoesNotAddExtensionError(string extension)
    {
        var course = new Course { CourseID = 9999, Title = "Test", Credits = 3, DepartmentID = 1 };
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.Length).Returns(100);
        mockFile.Setup(f => f.FileName).Returns($"test{extension}");
        mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = _controller.Create(course, mockFile.Object);

        // Should NOT have extension-related error
        if (_controller.ModelState.ContainsKey("teachingMaterialImage"))
        {
            var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
            Assert.DoesNotContain(errors, e => e.ErrorMessage.Contains("valid image file"));
        }
    }

