using Xunit;
using ContosoUniversity.Models;
using System;

namespace ContosoUniversity.Tests.Models;

public class PersonTests
{
    [Fact]
    public void FullName_ReturnsLastNameCommaFirstName()
    {
        // Use Student since Person is abstract
        var person = new Student
        {
            FirstMidName = "Carson",
            LastName = "Alexander",
            EnrollmentDate = DateTime.Today
        };

        Assert.Equal("Alexander, Carson", person.FullName);
    }

    [Fact]
    public void FullName_WithDifferentNames_FormatsCorrectly()
    {
        var person = new Instructor
        {
            FirstMidName = "Kim",
            LastName = "Abercrombie",
            HireDate = DateTime.Today
        };

        Assert.Equal("Abercrombie, Kim", person.FullName);
    }

    [Theory]
    [InlineData("John", "Doe", "Doe, John")]
    [InlineData("A", "B", "B, A")]
    [InlineData("Mary Jane", "Watson", "Watson, Mary Jane")]
    public void FullName_VariousNames_FormatsCorrectly(string first, string last, string expected)
    {
        var person = new Student
        {
            FirstMidName = first,
            LastName = last,
            EnrollmentDate = DateTime.Today
        };

        Assert.Equal(expected, person.FullName);
    }
}

public class ErrorViewModelTests
{
    [Fact]
    public void ShowRequestId_NonEmpty_ReturnsTrue()
    {
        var model = new ErrorViewModel { RequestId = "abc-123" };
        Assert.True(model.ShowRequestId);
    }

    [Fact]
    public void ShowRequestId_Null_ReturnsFalse()
    {
        var model = new ErrorViewModel { RequestId = null };
        Assert.False(model.ShowRequestId);
    }

    [Fact]
    public void ShowRequestId_Empty_ReturnsFalse()
    {
        var model = new ErrorViewModel { RequestId = "" };
        Assert.False(model.ShowRequestId);
    }
}

using Xunit;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using System.Net;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestHelpers.CreateSeededContext();
        _controller = new StudentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    // ========== Index ==========

    [Fact]
    public void Index_NoParams_ReturnsViewWithStudents()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(3, model.Count); // 3 seeded students
    }

    [Fact]
    public void Index_DefaultSort_OrdersByLastNameAscending()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Alexander", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Anand", model[2].LastName);
    }

    [Fact]
    public void Index_NameDescSort_OrdersByLastNameDescending()
    {
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Anand", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Alexander", model[2].LastName);
    }

    [Fact]
    public void Index_DateSort_OrdersByEnrollmentDateAscending()
    {
        var result = _controller.Index("Date", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        // 2010, 2012, 2013
        Assert.Equal("Alexander", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Anand", model[2].LastName);
    }

    [Fact]
    public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
    {
        var result = _controller.Index("date_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Anand", model[0].LastName);  // 2013
        Assert.Equal("Alonso", model[1].LastName);  // 2012
        Assert.Equal("Alexander", model[2].LastName); // 2010
    }

    [Fact]
    public void Index_SearchByLastName_FiltersResults()
    {
        var result = _controller.Index(null, null, "Alexander", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_SearchByFirstName_FiltersResults()
    {
        var result = _controller.Index(null, null, "Meredith", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Alonso", model[0].LastName);
    }

    [Fact]
    public void Index_SearchWithNoMatch_ReturnsEmpty()
    {
        var result = _controller.Index(null, null, "Nonexistent", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Empty(model);
    }

    [Fact]
    public void Index_SearchString_SetsCurrentFilterViewBag()
    {
        var result = _controller.Index(null, null, "test", null) as ViewResult;

        Assert.Equal("test", _controller.ViewBag.CurrentFilter);
    }

    [Fact]
    public void Index_NewSearch_ResetsPageToOne()
    {
        // When searchString is non-null, page should reset to 1
        var result = _controller.Index(null, null, "Alexander", 5) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_NullSearch_UsesCurrentFilter()
    {
        var result = _controller.Index(null, "Alonso", null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Alonso", model[0].LastName);
    }

    [Fact]
    public void Index_SetsViewBagSortParms()
    {
        _controller.Index(null, null, null, null);

        Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
        Assert.Equal("Date", _controller.ViewBag.DateSortParm);
    }

    [Fact]
    public void Index_NameDescSortOrder_TogglesSortParm()
    {
        _controller.Index("name_desc", null, null, null);

        // When sortOrder is "name_desc", NameSortParm toggles to "" (ascending)
        Assert.Equal("", _controller.ViewBag.NameSortParm);
    }

    [Fact]
    public void Index_DateSortOrder_TogglesToDateDesc()
    {
        _controller.Index("Date", null, null, null);

        Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);
    }

    // ========== Details ==========

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        var result = _controller.Details(1) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result!.Model);
        Assert.Equal("Alexander", student.LastName);
        Assert.Equal("Carson", student.FirstMidName);
    }

    [Fact]
    public void Details_ValidId_IncludesEnrollmentsWithCourse()
    {
        var result = _controller.Details(1) as ViewResult;

        var student = Assert.IsType<Student>(result!.Model);
        Assert.NotNull(student.Enrollments);
        Assert.NotEmpty(student.Enrollments);
    }

    // ========== Create (GET) ==========

    [Fact]
    public void Create_GET_ReturnsViewWithDefaultDate()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result!.Model);
        Assert.Equal(DateTime.Today, student.EnrollmentDate);
    }

    // ========== Create (POST) ==========

    [Fact]
    public void Create_POST_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            FirstMidName = "New",
            LastName = "Student",
            EnrollmentDate = DateTime.Parse("2023-01-15")
        };

        var result = _controller.Create(student);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_POST_ValidStudent_AddsToDatabase()
    {
        var student = new Student
        {
            FirstMidName = "New",
            LastName = "Student",
            EnrollmentDate = DateTime.Parse("2023-01-15")
        };

        _controller.Create(student);

        Assert.Equal(4, _context.Students.Count());
        var added = _context.Students.First(s => s.LastName == "Student");
        Assert.Equal("New", added.FirstMidName);
        Assert.Equal(DateTime.Parse("2023-01-15"), added.EnrollmentDate);
    }

    [Fact]
    public void Create_POST_DefaultEnrollmentDate_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Bad",
            LastName = "Date",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Create_POST_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "",
            EnrollmentDate = DateTime.Parse("2023-01-15")
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal(student, result!.Model);
    }

    [Fact]
    public void Create_POST_DateBeforeSqlMin_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "User",
            EnrollmentDate = new DateTime(1752, 1, 1)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    // ========== Edit (GET) ==========

    [Fact]
    public void Edit_GET_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_GET_ValidId_ReturnsViewWithStudent()
    {
        var result = _controller.Edit(1) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result!.Model);
        Assert.Equal("Alexander", student.LastName);
    }

    [Fact]
    public void Edit_GET_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Edit(999);

        Assert.IsType<NotFoundResult>(result);
    }

    // ========== Edit (POST) ==========

    [Fact]
    public void Edit_POST_ValidStudent_RedirectsToIndex()
    {
        var student = _context.Students.AsNoTracking().First(s => s.ID == 1);
        student.FirstMidName = "Updated";

        var result = _controller.Edit(student);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_POST_ValidStudent_UpdatesDatabase()
    {
        var student = _context.Students.AsNoTracking().First(s => s.ID == 1);
        student.FirstMidName = "UpdatedName";

        _controller.Edit(student);

        var updated = _context.Students.AsNoTracking().First(s => s.ID == 1);
        Assert.Equal("UpdatedName", updated.FirstMidName);
    }

    [Fact]
    public void Edit_POST_DefaultEnrollmentDate_AddsModelError()
    {
        var student = new Student
        {
            ID = 1,
            FirstMidName = "Test",
            LastName = "User",
            EnrollmentDate = default(DateTime)
        };

        var result = _controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Edit_POST_InvalidModelState_ReturnsViewWithStudent()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            ID = 1,
            FirstMidName = "Test",
            LastName = "",
            EnrollmentDate = DateTime.Parse("2023-01-15")
        };

        var result = _controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal(student, result!.Model);
    }

    // ========== Delete (GET) ==========

    [Fact]
    public void Delete_GET_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_GET_ValidId_ReturnsViewWithStudent()
    {
        var result = _controller.Delete(1) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result!.Model);
        Assert.Equal("Alexander", student.LastName);
    }

    [Fact]
    public void Delete_GET_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Delete(999);

        Assert.IsType<NotFoundResult>(result);
    }

    // ========== DeleteConfirmed (POST) ==========

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
    {
        var result = _controller.DeleteConfirmed(1);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(2, _context.Students.Count());
        Assert.Null(_context.Students.Find(1));
    }

    [Fact]
    public void DeleteConfirmed_ValidId_ReducesStudentCount()
    {
