    {
        using var context = TestHelpers.CreateInMemoryContext();

        var instructor = new Instructor { ID = 10, FirstMidName = "A", LastName = "B", HireDate = DateTime.Today };
        var course = new Course { CourseID = 100, Title = "Test", Credits = 3, DepartmentID = 0 };
        context.Instructors.Add(instructor);
        context.Courses.Add(course);
        context.SaveChanges();

        var ca = new CourseAssignment { CourseID = 100, InstructorID = 10 };
        context.CourseAssignments.Add(ca);
        context.SaveChanges();

        var found = context.CourseAssignments.Find(100, 10);
        Assert.NotNull(found);
        Assert.Equal(100, found!.CourseID);
        Assert.Equal(10, found.InstructorID);
    }

