    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _mockEnv;
    private readonly Mock<ILogger<CoursesController>> _mockLogger;

    public CoursesControllerTests()
    {
        _context = TestHelpers.CreateSeededContext();
        _mockEnv = new Mock<IWebHostEnvironment>();
        _mockEnv.Setup(e => e.WebRootPath).Returns((string?)null);
        _mockEnv.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _mockLogger = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    // ========== Index ==========

    [Fact]
    public void Index_ReturnsViewWithAllCourses()
    {
        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Course>>(result!.Model);
        Assert.Equal(2, model.Count);
    }

    [Fact]
    public void Index_CoursesIncludeDepartment()
    {
        var result = _controller.Index() as ViewResult;

        var model = Assert.IsAssignableFrom<List<Course>>(result!.Model);
        Assert.All(model, c => Assert.NotNull(c.Department));
    }

    // ========== Details ==========

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithCourse()
    {
        var result = _controller.Details(1050) as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result!.Model);
        Assert.Equal("Chemistry", course.Title);
        Assert.Equal(3, course.Credits);
    }

    [Fact]
    public void Details_ValidId_IncludesDepartment()
    {
        var result = _controller.Details(1050) as ViewResult;

        var course = Assert.IsType<Course>(result!.Model);
        Assert.NotNull(course.Department);
        Assert.Equal("English", course.Department.Name);
    }

    // ========== Create (GET) ==========

    [Fact]
    public void Create_GET_ReturnsViewWithEmptyCourse()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result!.Model);
        Assert.Equal(0, course.CourseID);
    }

    [Fact]
    public void Create_GET_PopulatesDepartmentDropdown()
    {
        _controller.Create();

        Assert.NotNull(_controller.ViewBag.DepartmentID);
    }

    // ========== Create (POST) ==========

    [Fact]
    public void Create_POST_ValidCourse_NoFile_RedirectsToIndex()
    {
        var course = new Course
        {
            CourseID = 9999,
            Title = "New Course",
            Credits = 4,
            DepartmentID = 1
        };

        var result = _controller.Create(course, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_POST_ValidCourse_SavesToDB()
    {
        var course = new Course
        {
            CourseID = 9999,
            Title = "New Course",
            Credits = 4,
            DepartmentID = 1
        };

        _controller.Create(course, null!);

        Assert.Equal(3, _context.Courses.Count());
        var saved = _context.Courses.Find(9999);
        Assert.NotNull(saved);
        Assert.Equal("New Course", saved!.Title);
        Assert.Equal(4, saved.Credits);
    }

    [Fact]
    public void Create_POST_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 9999, Title = "", Credits = 3, DepartmentID = 1 };

        var result = _controller.Create(course, null!) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal(course, result!.Model);
    }

    [Fact]
    public void Create_POST_InvalidFileExtension_ReturnsViewWithError()
    {
        var course = new Course { CourseID = 9999, Title = "Test", Credits = 3, DepartmentID = 1 };
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.Length).Returns(100);
        mockFile.Setup(f => f.FileName).Returns("test.exe");

        var result = _controller.Create(course, mockFile.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Create_POST_FileTooLarge_ReturnsViewWithError()
    {
        var course = new Course { CourseID = 9999, Title = "Test", Credits = 3, DepartmentID = 1 };
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.Length).Returns(10 * 1024 * 1024); // 10MB
        mockFile.Setup(f => f.FileName).Returns("test.jpg");

        var result = _controller.Create(course, mockFile.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
        Assert.Contains(errors, e => e.ErrorMessage.Contains("5MB"));
    }

    [Theory]
    [InlineData(".jpg")]
    [InlineData(".jpeg")]
    [InlineData(".png")]
    [InlineData(".gif")]
    [InlineData(".bmp")]
    public void Create_POST_ValidImageExtension_DoesNotAddExtensionError(string extension)
    {
        var course = new Course { CourseID = 9999, Title = "Test", Credits = 3, DepartmentID = 1 };
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.Length).Returns(100);
        mockFile.Setup(f => f.FileName).Returns($"test{extension}");
        mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = _controller.Create(course, mockFile.Object);

        // Should NOT have extension-related error
        if (_controller.ModelState.ContainsKey("teachingMaterialImage"))
        {
            var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
            Assert.DoesNotContain(errors, e => e.ErrorMessage.Contains("valid image file"));
        }
    }

    // ========== Edit (GET) ==========

    [Fact]
    public void Edit_GET_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_GET_ValidId_ReturnsViewWithCourse()
    {
        var result = _controller.Edit(1050) as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result!.Model);
        Assert.Equal("Chemistry", course.Title);
    }

    [Fact]
    public void Edit_GET_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Edit(99999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_GET_PopulatesDepartmentDropdown()
    {
        _controller.Edit(1050);

        Assert.NotNull(_controller.ViewBag.DepartmentID);
    }

    // ========== Edit (POST) ==========

    [Fact]
    public void Edit_POST_ValidCourse_NoFile_RedirectsToIndex()
    {
        var course = _context.Courses.AsNoTracking().First(c => c.CourseID == 1050);
        course.Title = "Updated Chemistry";

        var result = _controller.Edit(course, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_POST_ValidCourse_UpdatesDatabase()
    {
        var course = _context.Courses.AsNoTracking().First(c => c.CourseID == 1050);
        course.Title = "Advanced Chemistry";

        _controller.Edit(course, null!);

        var updated = _context.Courses.AsNoTracking().First(c => c.CourseID == 1050);
        Assert.Equal("Advanced Chemistry", updated.Title);
    }

    [Fact]
    public void Edit_POST_InvalidModelState_ReturnsViewWithCourse()
    {
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 1050, Title = "", Credits = 3, DepartmentID = 1 };

        var result = _controller.Edit(course, null!) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal(course, result!.Model);
    }

    [Fact]
    public void Edit_POST_InvalidFileExtension_ReturnsError()
    {
        var course = _context.Courses.AsNoTracking().First(c => c.CourseID == 1050);
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.Length).Returns(100);
        mockFile.Setup(f => f.FileName).Returns("test.txt");

        var result = _controller.Edit(course, mockFile.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Edit_POST_FileTooLarge_ReturnsError()
    {
        var course = _context.Courses.AsNoTracking().First(c => c.CourseID == 1050);
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024);
        mockFile.Setup(f => f.FileName).Returns("test.jpg");

        var result = _controller.Edit(course, mockFile.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    // ========== Delete (GET) ==========

    [Fact]
    public void Delete_GET_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_GET_ValidId_ReturnsViewWithCourse()
    {
        var result = _controller.Delete(1050) as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result!.Model);
        Assert.Equal("Chemistry", course.Title);
    }

    // ========== DeleteConfirmed (POST) ==========

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesCourseAndRedirects()
    {
        var result = _controller.DeleteConfirmed(1050);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Null(_context.Courses.Find(1050));
    }

    [Fact]
    public void DeleteConfirmed_ValidId_ReducesCourseCount()
    {
        var initialCount = _context.Courses.Count();

        _controller.DeleteConfirmed(1050);

        Assert.Equal(initialCount - 1, _context.Courses.Count());
    }
}

