using Xunit;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;

namespace ContosoUniversity.Tests.Controllers;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestHelpers.CreateSeededContext();
        _controller = new InstructorsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    // ========== Index ==========

    [Fact]
    public void Index_NoParams_ReturnsViewWithInstructors()
    {
        var result = _controller.Index(null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result!.Model);
        Assert.NotNull(model.Instructors);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_InstructorsOrderedByLastName()
    {
        var result = _controller.Index(null, null) as ViewResult;

        var model = Assert.IsType<InstructorIndexData>(result!.Model);
        var instructors = model.Instructors.ToList();
        Assert.Equal("Abercrombie", instructors[0].LastName);
        Assert.Equal("Fakhouri", instructors[1].LastName);
    }

    [Fact]
    public void Index_WithInstructorId_PopulatesCourses()
    {
        var result = _controller.Index(1, null) as ViewResult;

        var model = Assert.IsType<InstructorIndexData>(result!.Model);
        Assert.NotNull(model.Courses);
        Assert.NotEmpty(model.Courses);
    }

    [Fact]
    public void Index_WithInstructorId_SetsViewBagInstructorID()
    {
        _controller.Index(1, null);

        Assert.Equal(1, _controller.ViewBag.InstructorID);
    }

    // ========== Details ==========

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithInstructor()
    {
        var result = _controller.Details(1) as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result!.Model);
        Assert.Equal("Abercrombie", instructor.LastName);
        Assert.Equal("Kim", instructor.FirstMidName);
    }

    [Fact]
    public void Details_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Details(999);

        Assert.IsType<NotFoundResult>(result);
    }

    // ========== Create (GET) ==========

    [Fact]
    public void Create_GET_ReturnsViewWithNewInstructor()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result!.Model);
        Assert.NotNull(instructor.CourseAssignments);
        Assert.Empty(instructor.CourseAssignments);
    }

    [Fact]
    public void Create_GET_PopulatesCourseData()
    {
        _controller.Create();

        Assert.NotNull(_controller.ViewBag.Courses);
        var courses = Assert.IsAssignableFrom<List<AssignedCourseData>>(_controller.ViewBag.Courses);
        Assert.Equal(2, courses.Count); // 2 seeded courses
    }

    // ========== Create (POST) ==========

    [Fact]
    public void Create_POST_ValidInstructor_NoSelectedCourses_RedirectsToIndex()
    {
        var instructor = new Instructor
        {
            FirstMidName = "New",
            LastName = "Teacher",
            HireDate = DateTime.Parse("2020-01-01")
        };

        var result = _controller.Create(instructor, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_POST_ValidInstructor_SavesToDB()
    {
        var instructor = new Instructor
        {
            FirstMidName = "New",
            LastName = "Teacher",
            HireDate = DateTime.Parse("2020-01-01")
        };

        _controller.Create(instructor, null!);

        Assert.Equal(3, _context.Instructors.Count());
        var saved = _context.Instructors.First(i => i.LastName == "Teacher");
        Assert.Equal("New", saved.FirstMidName);
    }

    [Fact]
    public void Create_POST_WithSelectedCourses_CreatesCourseAssignments()
    {
        var instructor = new Instructor
        {
            FirstMidName = "New",
            LastName = "Teacher",
            HireDate = DateTime.Parse("2020-01-01")
        };

        _controller.Create(instructor, new[] { "1050", "4022" });

        var saved = _context.Instructors
            .Include(i => i.CourseAssignments)
            .First(i => i.LastName == "Teacher");
        Assert.Equal(2, saved.CourseAssignments.Count);
    }

    [Fact]
    public void Create_POST_InvalidModelState_ReturnsViewAndPopulatesCourses()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor
        {
            FirstMidName = "Test",
            LastName = "",
            HireDate = DateTime.Today
        };

        var result = _controller.Create(instructor, null!) as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    // ========== Delete (GET) ==========

    [Fact]
    public void Delete_GET_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_GET_ValidId_ReturnsViewWithInstructor()
    {
        var result = _controller.Delete(1) as ViewResult;

        Assert.NotNull(result);
        var instructor = Assert.IsType<Instructor>(result!.Model);
        Assert.Equal("Abercrombie", instructor.LastName);
    }

    [Fact]
    public void Delete_GET_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Delete(999);

        Assert.IsType<NotFoundResult>(result);
    }

    // ========== DeleteConfirmed (POST) ==========

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesInstructorAndRedirects()
    {
        // Use instructor 2 (Fakhouri) who is department admin for dept 2
        var result = _controller.DeleteConfirmed(2);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Null(_context.Instructors.Find(2));
    }

    [Fact]
    public void DeleteConfirmed_InstructorIsDeptAdmin_NullsOutDepartmentAdmin()
    {
        // Instructor 2 is admin for department 2
        _controller.DeleteConfirmed(2);

        var dept = _context.Departments.Find(2);
        Assert.NotNull(dept);
        Assert.Null(dept!.InstructorID);
    }

    [Fact]
    public void DeleteConfirmed_ReducesInstructorCount()
    {
        var initialCount = _context.Instructors.Count();

        _controller.DeleteConfirmed(2);

        Assert.Equal(initialCount - 1, _context.Instructors.Count());
    }
}

using Xunit;
